/* DepAtlas —— 深色专业工具主题；token 内聚于 :root */
:root {
  --bg: #0b101d;
  --panel: #10182a;
  --panel-2: #0d1424;
  --line: #223052;
  --line-soft: #1a2540;
  --text: #dbe4f5;
  --muted: #8b9bbd;
  --faint: #5f6f92;
  --accent: #38e1ff;
  --crit: #d29a45;
  --danger: #ff7a7a;
  --node-fill: #17223c;
  --node-line: #2b3c63;
}

* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 14px/1.5 "Segoe UI", system-ui, "Microsoft YaHei", "PingFang SC", sans-serif;
  overflow: hidden;
}
body.state-error #error-panel { display: block; }
#error-panel { display: none; padding: 40px; color: var(--danger); }
.noscript { padding: 24px; color: var(--danger); }

#app { display: grid; grid-template-rows: auto auto 1fr; height: 100vh; }

/* ---------- 顶栏 ---------- */
#topbar {
  display: flex; align-items: center; gap: 18px;
  padding: 10px 18px;
  background: linear-gradient(180deg, #111a30, #0e1526);
  border-bottom: 1px solid var(--line);
}
.brand { display: flex; align-items: center; gap: 10px; min-width: 300px; }
.logo { color: var(--accent); font-size: 22px; }
.brand h1 { margin: 0; font-size: 17px; letter-spacing: .2px; }
.brand h1 em { font-style: normal; color: var(--muted); font-weight: 500; font-size: 13px; margin-left: 6px; }
.tagline { margin: 0; font-size: 11px; color: var(--faint); }

.search-wrap { position: relative; flex: 0 1 340px; }
#search {
  width: 100%; padding: 7px 12px;
  background: var(--panel-2); color: var(--text);
  border: 1px solid var(--line); border-radius: 8px;
  font-size: 13px; outline: none;
}
#search:focus { border-color: var(--accent); }
#search-results {
  position: absolute; z-index: 30; top: calc(100% + 6px); left: 0; right: 0;
  margin: 0; padding: 6px; list-style: none;
  background: #131c33; border: 1px solid var(--line); border-radius: 10px;
  box-shadow: 0 12px 30px rgba(0,0,0,.5);
  max-height: 320px; overflow: auto;
}
#search-results li.none { padding: 8px 10px; color: var(--muted); font-size: 12px; }
#search-results button {
  display: flex; align-items: center; gap: 8px; width: 100%;
  padding: 7px 9px; border: 0; border-radius: 7px;
  background: transparent; color: var(--text); font-size: 13px; text-align: left; cursor: pointer;
}
#search-results button em { font-style: normal; color: var(--muted); font-size: 12px; }
#search-results button span { margin-left: auto; color: var(--faint); font-size: 11px; }
#search-results button:hover, #search-results button.hover { background: #1c2947; }

.filter { display: flex; align-items: center; gap: 6px; color: var(--muted); font-size: 12.5px; cursor: pointer; }
.filter input { accent-color: var(--accent); }

.btn {
  padding: 7px 14px; border: 1px solid var(--line); border-radius: 8px;
  background: var(--panel-2); color: var(--text); font-size: 13px; cursor: pointer;
}
.btn:hover { border-color: var(--accent); color: #fff; }
.btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
.btn.ghost { background: transparent; color: var(--muted); }
.btn.small { padding: 4px 10px; font-size: 12px; }
.btn.on { border-color: var(--accent); color: var(--accent); }

/* ---------- 跟随路径条 ---------- */
#trailbar {
  display: flex; align-items: center; gap: 14px;
  padding: 6px 18px; min-height: 38px;
  background: var(--panel-2); border-bottom: 1px solid var(--line);
}
.ctx { color: var(--muted); font-size: 12px; white-space: nowrap; }
.ctx b { color: var(--accent); font-size: 13px; }
#trail {
  display: flex; align-items: center; gap: 4px; flex: 1;
  margin: 0; padding: 0; list-style: none; overflow-x: auto;
}
.chip {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 3px 10px; border: 1px solid var(--line); border-radius: 999px;
  background: var(--panel); color: var(--text); font-size: 12px; cursor: pointer; white-space: nowrap;
}
.chip:hover { border-color: var(--accent); }
.chip.current { border-color: var(--accent); color: var(--accent); background: rgba(56,225,255,.08); }
.chip .dot, .dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; }
.tsep { color: var(--faint); font-size: 13px; white-space: nowrap; }
.tsep em { font-style: normal; font-size: 10.5px; color: var(--faint); margin-left: 3px; }

/* ---------- 主区 ---------- */
#main { display: grid; grid-template-columns: 1fr 344px; min-height: 0; }

#map-panel { position: relative; display: flex; flex-direction: column; min-width: 0; background:
  radial-gradient(1100px 600px at 42% 40%, #0e1626 0%, var(--bg) 70%); }
#map { flex: 1; width: 100%; min-height: 0; display: block; }
.map-footnote {
  display: flex; align-items: center; justify-content: space-between; gap: 16px;
  padding: 4px 18px 8px; color: var(--faint); font-size: 11.5px;
}
.legend { display: flex; gap: 14px; white-space: nowrap; }
.legend .sw { display: inline-block; width: 22px; height: 0; margin-right: 5px; vertical-align: middle; border-top: 2px solid; }
.sw.call { border-color: #5d78a6; }
.sw.data { border-color: #3f7d74; border-top-style: dashed; }
.sw.crit { border-color: var(--crit); border-top-width: 3px; }
.sw.trail { border-color: var(--accent); border-top-width: 3px; }

/* SVG 元素 */
.band { fill: rgba(255,255,255,.016); stroke: var(--line-soft); stroke-width: 1; }
.tier-label { fill: var(--muted); font-size: 12px; font-weight: 600; letter-spacing: .5px; }

.edge { fill: none; transition: opacity .18s; pointer-events: none; }
.edge.call { stroke: #5d78a6; stroke-width: 1.5; }
.edge.data { stroke: #3f7d74; stroke-width: 1.5; stroke-dasharray: 5 4; }
.edge.crit { stroke: var(--crit); stroke-width: 2.4; }
.edge.crit.data { stroke-dasharray: 7 4; }
.edge.trail { stroke: var(--accent); stroke-width: 3; }
.edge.sel { stroke: #eaf3ff; stroke-width: 2.6; }
.edge.dim { opacity: .1; }
svg.no-data .edge.data:not(.trail):not(.sel) { opacity: .05; }

.edge-hit { fill: none; stroke: #000; stroke-opacity: 0; stroke-width: 16; cursor: pointer; }
.edge-hit:focus { outline: none; }
.edge-hit:focus-visible { stroke: rgba(56,225,255,.55); stroke-opacity: 1; stroke-width: 3; stroke-dasharray: 3 4; }
.edge-hit.dim { pointer-events: auto; }

g.node { cursor: pointer; }
g.node:focus { outline: none; }
g.node:focus-visible .node-box { stroke: #fff; stroke-width: 2.2; }
.node-box { fill: var(--node-fill); stroke: var(--node-line); stroke-width: 1.1; transition: opacity .18s; }
g.node:hover .node-box { stroke: #5b83c9; }
g.node.trail .node-box { stroke: var(--accent); stroke-width: 1.7; }
g.node.sel .node-box { stroke: #ffffff; stroke-width: 2; fill: #1d2c50; }
g.node.closure .node-box { stroke: var(--crit); stroke-width: 1.7; stroke-dasharray: 4 3; }
g.node.dim { opacity: .13; }
g.node.dim:hover { opacity: .6; }
.node-id { fill: #e2eafc; font-size: 12px; font-weight: 600; font-family: Consolas, "Segoe UI", monospace; }
.node-zh { fill: #8496b8; font-size: 10.5px; }

/* ---------- 详情面板 ---------- */
#inspector {
  background: var(--panel); border-left: 1px solid var(--line);
  overflow-y: auto; padding: 14px 16px 24px;
}
.empty-state {
  margin-top: 26px; padding: 18px 16px;
  border: 1px dashed var(--line); border-radius: 10px; color: var(--muted);
}
.empty-state h3 { margin: 0 0 8px; font-size: 13.5px; color: var(--text); }
.empty-state p { margin: 6px 0; font-size: 12.5px; }
.empty-state .hint { color: var(--faint); }
.empty-state b { color: var(--accent); font-weight: 600; }

.insp-title { display: flex; align-items: center; gap: 8px; margin: 2px 0 4px; font-size: 15.5px; font-family: Consolas, "Segoe UI", monospace; }
.insp-title small { color: var(--muted); font-family: "Segoe UI", "Microsoft YaHei", sans-serif; font-weight: 500; font-size: 12.5px; }
.insp-desc { margin: 2px 0 4px; color: var(--muted); font-size: 12.5px; }
.insp-meta { margin: 0 0 10px; color: var(--faint); font-size: 11.5px; }

.stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; margin: 10px 0 4px; }
.stat {
  padding: 7px 4px; text-align: center;
  background: var(--panel-2); border: 1px solid var(--line-soft); border-radius: 8px;
}
.stat b { display: block; font-size: 16px; color: var(--accent); }
.stat span { font-size: 10.5px; color: var(--muted); }

.rel-group { margin-top: 12px; }
.rel-group h4 { margin: 0 0 6px; font-size: 12.5px; color: var(--text); }
.rel-group h4 i { font-style: normal; color: var(--faint); font-weight: 400; margin-left: 4px; }
.rel-list { list-style: none; margin: 0; padding: 0; }
.rel-none { margin: 2px 0; color: var(--faint); font-size: 12px; }
button.rel {
  display: flex; align-items: center; gap: 6px; width: 100%;
  margin: 3px 0; padding: 6px 9px;
  background: var(--panel-2); border: 1px solid var(--line-soft); border-radius: 8px;
  color: var(--text); font-size: 12.5px; text-align: left; cursor: pointer;
  font-family: Consolas, "Segoe UI", monospace;
}
button.rel em { font-style: normal; color: var(--muted); font-size: 11.5px; font-family: "Segoe UI", "Microsoft YaHei", sans-serif; }
button.rel:hover { border-color: var(--accent); }
button.rel .dir { color: var(--accent); font-weight: 700; }
button.rel .flag {
  margin-left: auto; font-style: normal; font-size: 10px; color: var(--crit);
  border: 1px solid rgba(210,154,69,.5); border-radius: 4px; padding: 0 4px;
}
.closure-actions { display: flex; gap: 8px; margin-top: 14px; }
.panel-hint { margin-top: 12px; color: var(--faint); font-size: 11.5px; }

.edge-line { display: flex; align-items: center; gap: 8px; margin: 10px 0; font-family: Consolas, "Segoe UI", monospace; font-size: 13.5px; }
.edge-line .arr { color: var(--accent); font-style: normal; font-weight: 700; }
.edge-line b { color: var(--accent); }
.edge-meta { display: grid; grid-template-columns: 64px 1fr; gap: 4px 10px; margin: 8px 0; font-size: 12.5px; }
.edge-meta dt { color: var(--faint); }
.edge-meta dd { margin: 0; }

/* ---------- 提示 ---------- */
#tooltip {
  position: fixed; z-index: 50; pointer-events: none;
  max-width: 220px; padding: 7px 10px;
  background: #1b2743; border: 1px solid var(--line); border-radius: 8px;
  color: var(--text); font-size: 12px; line-height: 1.45;
  box-shadow: 0 8px 22px rgba(0,0,0,.45);
}
#tooltip b { font-family: Consolas, monospace; }

