    );
    const synonymHit = [...SHELL_TERMS.synonyms].some((synonym) => scannedText.includes(synonym));
    const shellTriggered =
      representation.primary.type === "cards" || wordBoundary.test(scannedText) || synonymHit;

    if (shellTriggered) {
      const justification = representation.justification_vs_shape;
      const shapeVariables = [
        "cardinality",
        "relationality",
        "hierarchy",
        "temporality",
        "density",
        "dimensionality",
        "spatiality",
        "volatility",
        "uncertainty",
        "comparison_need",
      ];
      const referencesShape =
        justification !== undefined && shapeVariables.some((variable) => justification.includes(variable));
      if (!referencesShape) {
        codes.push("DECISION_DEFAULT_SHELL_UNJUSTIFIED");
        const allDecisionText = [
          representation.primary.reason,
          ...representation.supporting.map((entry) => entry.reason),
          ...representation.rejected.map((entry) => entry.option),
          ...parsed.data.major_choices.flatMap((choice) => [choice.choice, choice.rationale]),
        ].join(" ");
        const englishMatch = wordBoundary.exec(allDecisionText)?.[1];
        const synonymMatch = SHELL_TERMS.synonyms
          .map((synonym, index) => (allDecisionText.includes(synonym) ? SHELL_TERMS.terms[index] : undefined))
          .find((matched) => matched !== undefined);
        const triggeredTerm =
          representation.primary.type === "cards" ? "cards" : englishMatch ?? synonymMatch;
        const myth = triggeredTerm !== undefined ? SHELL_MYTH_MAP[triggeredTerm as keyof typeof SHELL_MYTH_MAP] : undefined;
        issues.push(
          "Default-shell representation detected (dashboard / cards / tabs / modal). " +
            (justification === undefined
              ? "representation.justification_vs_shape is required."
              : "justification_vs_shape must reference at least one information_shape variable (cardinality, relationality, …).") +
            (myth === undefined ? "" : ` Refuted default on record: ${myth} — read its refutation before arguing.`) +
            " Negative knowledge mandates argumentation, not prohibition (research §48C).",
        );
      }
    }

    if (representation.rejected.length === 0) {
      warnings.push(
        "DECISION_NO_REJECTED_REPRESENTATION: the representation portfolio declares no rejected option; every decided portfolio names what it declined (PRAX-P-005).",
      );
    }
  }
  if (!context.routedPatternIds.has(chosen)) {
    codes.push("DECISION_PATTERN_NOT_ROUTED");
    issues.push(`Chosen Pattern ${chosen} was not returned by the Design Router.`);
  }
  if (!context.inspectedAtLeastL1.has(chosen)) {
    codes.push("DECISION_PATTERN_NOT_INSPECTED");
    issues.push(`Chosen Pattern ${chosen} was not inspected to at least L1.`);
  }
  if (
    context.plausibleAlternativeCount > 1 &&
    parsed.data.rejected.length === 0
  ) {
    codes.push("DECISION_ALTERNATIVE_NOT_REJECTED");
    issues.push("At least one plausible alternative must be explicitly rejected.");
  }
  const highImpactUnknowns = parsed.data.unresolved.filter(
    (unknown) => typeof unknown !== "string" && unknown.impact === "high",
  );
  if (highImpactUnknowns.length > 0) {
    codes.push("DECISION_HIGH_IMPACT_UNRESOLVED");
    issues.push("High-impact design decisions remain unresolved.");
  }

  const vocabulary = decisionReferenceVocabulary(context.frame, context.context);
  const semantic = semanticFindings(parsed.data, context, vocabulary);
  if (semantic.acceptedOverride !== undefined) {
    const override = semantic.acceptedOverride;
    warnings.push(
      `information_hierarchy deviates from the pattern contract under an override accepted by ${override.accepted_by}: ${override.basis} (risks: ${override.risks.join("; ")})`,
    );
  }
  for (const finding of semantic.issues) {
    codes.push(finding.code);
    issues.push(finding.message);
  }

  if (parsed.data.primary_structure.confidence === "low") {
    warnings.push("The primary structure decision has low confidence.");
  }

  // DECISION_DEFAULT_SHELL_UNJUSTIFIED is a REVIEW (argumentation demanded,
  // never prohibition — spec §6.3 / §12 decision 7); other issues stay EXPAND
  const reviewOnly = issues.length > 0 && codes.includes("DECISION_DEFAULT_SHELL_UNJUSTIFIED");
  return {
    status: issues.length === 0 ? (warnings.length === 0 ? "PASS" : "WARN") : reviewOnly ? "REVIEW" : "EXPAND",
    issues,
    warnings,
    codes,
    value: parsed.data,
  };
}

export function validateCapabilityMap(
  input: unknown,
): ArtifactValidation<CapabilityMap> {
  const parsed = CapabilityMapSchema.safeParse(input);
  if (!parsed.success) {
    return {
      status: "RETRY",
      issues: zodIssues(parsed.error),
      warnings: [],
    };
  }

  const issues: string[] = [];
  const warnings: string[] = [];
  for (const need of parsed.data.needs) {
    if ((need.status === "gap" || need.status === "blocked") && need.resolution === undefined) {
      issues.push(
        `${need.id} is ${need.status} but has no explicit resolution type and notes.`,
      );
    }
    if (need.status === "blocked") {
      issues.push(`${need.id} remains blocked.`);
    }
    if (need.status === "gap" && need.resolution?.type === "explicit_compromise") {
      warnings.push(`${need.id} advances with an explicit UX compromise.`);

